package invensoft.testdata;

public class ProductDetailRow {
    private String product;
    private String units;
    private String packing;
    private String qty;
    private String uom;
    private String noOfLots;
    private String price;
    private String targetType;
    private String targetDateRange;
    private String tradeMonth;
    private String positionMonth;
    private String quality;
    private String certificationPremium;

    public String getProduct() {
        return product;
    }
    public void setProduct(String product) {

        this.product = product;
    }

    public String getUnits() {
        return units;
    }
    public void setUnits(String units) {

        this.units = units;
    }

    public String getPacking() {
        return packing;
    }
    public void setPacking(String packing) {
        this.packing = packing;
    }

    public String getQty() {
        return qty;
    }
    public void setQty(String qty) {
        this.qty = qty;
    }

    public String getUom() {
        return uom;
    }
    public void setUom(String uom) {
        this.uom = uom;
    }

    public String getNoOfLots() {
        return noOfLots;
    }
    public void setNoOfLots(String noOfLots) {
        this.noOfLots = noOfLots;
    }

    public String getPrice() {
        return price;
    }
    public void setPrice(String price) {
        this.price = price;
    }

    public String getTargetType() {
        return targetType;
    }
    public void setTargetType(String targetType) {
        this.targetType = targetType;
    }

    public String getTargetDateRange() {
        return targetDateRange;
    }
    public void setTargetDateRange(String targetDateRange) {
        this.targetDateRange = targetDateRange;
    }

    public String getTradeMonth() {
        return tradeMonth;
    }
    public void setTradeMonth(String tradeMonth) {
        this.tradeMonth = tradeMonth;
    }

    public String getPositionMonth() {
        return positionMonth;
    }
    public void setPositionMonth(String positionMonth) {
        this.positionMonth = positionMonth;
    }

    public String getQuality() {
        return quality;
    }
    public void setQuality(String quality) {
        this.quality = quality;
    }

    public String getCertificationPremium() {
        return certificationPremium;
    }
    public void setCertificationPremium(String certificationPremium) {
        this.certificationPremium = certificationPremium;
    }
}